Lemma limbs_of_defined M q : forall (k : nat), L5.defined M q (8 * Z.of_nat k) -> 0 <= q -> q + 8 * Z.of_nat k <= 2 ^ 64 ->
  exists ws, length ws = k /\ Forall (fun w => 0 <= w < 2 ^ 64) ws /\ L5.limbs_at RSEGS M q ws.
Proof.
